    endpair[0].value=endpair[1].value=endpair[2].value=endpair[3].value=0;
    if (c.member) add_tc(g_keeper,TCI_VILLAGE_MEMBER,g_vm);
    g_village[0x3f]=c.village?0:1;
    g_has_shop=c.shop;
